const input = $input.first().json;

// Get AI output
let raw = input.output?.[0]?.content?.[0]?.text ?? input.output ?? input.text ?? '';

// If AI returned an object, don't JSON.parse it
if (typeof raw === 'object' && raw !== null) {
  return [
    {
      json: raw
    }
  ];
}

// Convert to string
raw = String(raw).trim();

// Remove markdown code fences if present
const cleaned = raw
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error(
    `AI returned invalid JSON. Raw response: ${cleaned.substring(0, 500)}`
  );
}

return [
  {
    json: parsed
  }
];

const data = $input.first().json;

const skills = Array.isArray(data.skills)
  ? data.skills
  : String(data.skills || '')
      .split(',')
      .map(s => s.trim())
      .filter(Boolean);

return [{
  json: {
      ...data,

      name: String(data.name || '').trim(),

      email: String(data.email || '')
        .trim()
        .toLowerCase(),

      phone: String(data.phone || '').trim(),

      skills,

      experience_years:
        Number(data.experience_years) || 0,

      education:
        String(data.education || '').trim(),

      current_role:
        String(data.current_role || '').trim(),

      certifications:
        Array.isArray(data.certifications)
          ? data.certifications
          : [],

      projects:
        Array.isArray(data.projects)
          ? data.projects
          : []
    }
