const data = $input.first().json;

const text = (data.text || '').trim();

const errors = [];

if (!text) {
  errors.push('Resume text could not be extracted');
}

if (text.length < 200) {
  errors.push('Resume content is too short');
}

const hasEmail = /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/i.test(text);

if (!hasEmail) {
  errors.push('Candidate email could not be detected');
}

return [{
  json: {
    ...data,
    resumeValid: errors.length === 0,
    validationErrors: errors,
    detectedEmail: hasEmail ? hasEmail[0] : null
  }
}];

const candidate = $input.first().json;

const aiScore = Number(candidate.match_score || 0);
const skillScore = Number(candidate.skill_match_score || 0);
const experienceScore = Number(candidate.experience_match_score || 0);
const educationScore = Number(candidate.education_match_score) || 0;

const finalScore = Math.round(
  (aiScore * 0.5) +
  (skillScore * 0.3) +
  (experienceScore * 0.2) + 
  (educationScore * 0.10)
);

let status;

if (finalScore >= 80) {
  status = 'SHORTLIST';
} else if (finalScore >= 60) {
  status = 'REVIEW';
} else {
  status = 'NOT_SHORTLISTED';
}

return [{
  json: {
    ...candidate,
    final_score: finalScore,
    hiring_status: status,
    evaluated_at: new Date().toISOString()
  }
}];

