const input = $input.first().json;

// Get the AI response from different possible OpenAI output structures
let raw =
  input.output?.[0]?.content?.[0]?.text ??
  input.output_text ??
  input.text ??
  input.output ??
  '';

// If the AI already returned an object, use it directly
if (typeof raw === 'object' && raw !== null) {
  return [
    {
      json: raw
    }
  ];
}

// Convert response to string
raw = String(raw).trim();

// Remove Markdown JSON code fences if AI added them
const cleaned = raw
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error(
    `AI Evaluation Result is not valid JSON.\nRaw response: ${cleaned.substring(0, 1000)}`
  );
}

// Return parsed evaluation result
return [
  {
    json: parsed
  }
];

const clean = $('Data Cleaning & Formatting').item.json;
const evaluation = $('Parse Evaluation Result').item.json;
const score = $('Calculate Final Candidate Score').item.json;
const job = $('Resume Valid?').item.json.info;

const education = Array.isArray(clean.education)
  ? clean.education.join(', ')
  : String(clean.education ?? '');

const experienceYears = Number(clean.experience_years);

if (!Number.isInteger(experienceYears)) {
  throw new Error(
    `experience_years must be an integer. Received: ${clean.experience_years}`
  );
}

return [{
  json: {
    name: clean.name ?? '',
    email: clean.email ?? '',
    phone: clean.phone ?? '',

    skills: JSON.stringify(
      Array.isArray(clean.skills) ? clean.skills : []
    ),

    experience_years: experienceYears,

    education,

    candidate_current_role: clean.current_role ?? '',
    job_title: job?.Title ?? '',

    match_score: Number(evaluation.match_score) || 0,
    skill_match_score: Number(evaluation.skill_match_score) || 0,
    experience_match_score: Number(evaluation.experience_match_score) || 0,
    education_match_score: Number(evaluation.education_match_score) || 0,

    final_score: Number(score.final_score) || 0,

    matched_skills: JSON.stringify(
      Array.isArray(score.matched_skills)
        ? score.matched_skills
        : []
    ),

    missing_required_skills: JSON.stringify(
      Array.isArray(score.missing_required_skills)
        ? score.missing_required_skills
        : []
    ),

    strengths: JSON.stringify(
      Array.isArray(score.strengths)
        ? score.strengths
        : []
    ),

    gaps: JSON.stringify(
      Array.isArray(score.gaps)
        ? score.gaps
        : []
    ),

    recommendation: score.recommendation ?? '',
    evaluation_reason: score.reason ?? ''
  }
}];
